window.ardaEmblem=function(key,size){var h=window.ARDA_HERALD[key];if(!h)return"";
 var s=size||40;
 if(h.file){return '<img src="'+h.file+'" width="'+s+'" height="'+Math.round(s*1.2)+'" loading="lazy" style="object-fit:contain;vertical-align:middle" alt="'+h.blazon.replace(/"/g,"")+'">';}
 if(h.forge&&window.ardaForgeDevice)return window.ardaForgeDevice(h.forge,s);
 return '<svg width="'+s+'" height="'+Math.round(s*1.2)+'" viewBox="0 0 40 48" style="vertical-align:middle"><use href="#em-'+key+'"/></svg>';};
window.ardaEmblemNote=function(key){var h=window.ARDA_HERALD[key];if(!h)return"";
 var BB={artwork:["#e9f3e4","#7aa86a","✔ Tolkien's device"],design:["#e6eef7","#6f8cae","✦ Tolkien's design, drawn here"],
         text:["#f2ecf7","#9a7ab5","✧ blazoned in the texts"],inferred:["#fdf3df","#d0a53c","◆ interpretive"],
         silent:["#efe8d6","#a89b80","◌ no device recorded"]};
 var q=BB[h.basis||(h.canon?"artwork":"inferred")];
 var tag='<span style="background:'+q[0]+';border:1px solid '+q[1]+';border-radius:8px;padding:0 6px;font-size:9.5px">'+q[2]+'</span>';
 var attr=h.canon?('recreation via <a href="'+h.src+'" target="_blank" style="color:#7a4a12">Wikimedia Commons</a>, '+h.license):('lore-derived '+h.author);
 return '<div style="font-size:11px;margin-top:3px">'+tag+' <span class="cite">'+h.blazon+'</span><br><span class="cite" style="font-size:10px">'+attr+'</span></div>';};

