 var doOne=function(symId,key){var h=window.ARDA_HERALD[key];if(!h||!h.file)return;
  var sym=document.getElementById(symId);if(!sym){sym=document.createElementNS(NS,"symbol");sym.id=symId;sym.setAttribute("viewBox","0 0 40 48");defs.appendChild(sym);}
  sym.innerHTML='<image href="'+h.file+'" x="0" y="0" width="40" height="48" preserveAspectRatio="xMidYMid meet"/>';};
 Object.keys(window.ARDA_HERALD).forEach(function(k){doOne("em-"+k,k);});
